{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Eluxadoline, the closest retrieved analogue, has ~1% absolute oral bioavailability in humans due to very low GI permeability and first-pass extraction; its amide/peptide-like, carboxylic-acid-containing scaffold supports low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Revefenacin, a large amide/carbamate with multiple H-bond donors and acceptors, has <3% absolute oral bioavailability in humans, supporting low F for the query's large polar amide/urea structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Terameprocol, a polymethoxyphenyl compound, has only ~2% oral bioavailability in patients, showing that extensive methoxyaromatic character does not ensure adequate absorption and supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Almorexant, containing a dimethoxyphenyl group and an amide, has ~11% absolute oral bioavailability in healthy subjects, below the 20% threshold, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Rigosertib reached 35% absolute oral bioavailability in fasting patients, a contradictory above-threshold value, but its fed-state F was 13.9% and it lacks the query's dense amide/urea H-bonding, so this evidence is weak.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Low is better supported. The closest and most functionally relevant analogues—eluxadoline, revefenacin, terameprocol, and almorexant—all have absolute oral bioavailability below 20%, often below 5%, and share the query's combination of multiple aromatic rings, methoxy groups, amide/urea linkages, and/or carboxylic acid that limit permeability. Higher-F comparators are less transferable because they are prodrug esters, basic amines, or have food-dependent/borderline values. Therefore predict low.",
  "evidence_gaps": [
    "No direct experimental PK or absolute bioavailability data for the query molecule.",
    "All retrieved analogues have low Morgan similarity (<0.3), limiting quantitative transferability.",
    "No permeability, efflux, solubility, or first-pass metabolism data specific to the query.",
    "Food effects and prodrug status of some comparators complicate extrapolation."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

